input.command:
cd ~/development/.tmp/stallion-rich/issues
cat > file.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
const titles = readFileSync("titles.txt", "utf8").trim().split("\n");
const gated = new Set([2, 3, 5, 7, 8]);
const nums = {};
const sleep = (ms) => Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
for (let i = 1; i <= 8; i++) {
  let body = readFileSync(`${i}.md`, "utf8").replace(/#N(\d)/g, (_, n) => `#${nums[n]}`);
  writeFileSync(`${i}.final.md`, body);
  const args = ["issue", "create", "-R", "mvhenten/stallion", "--title", titles[i - 1], "--body-file", `${i}.final.md`, "--label", "stage", "--label", "rich-tools"];
  if (gated.has(i)) args.push("--label", "needs-approval");
  for (let attempt = 0; ; attempt++) {
    try {
      const url = execFileSync("gh", args, { encoding: "utf8" }).trim();
      nums[i] = url.split("/").pop();
      console.log(`${i} -> #${nums[i]} ${titles[i - 1]}`);
      break;
    } catch (e) {
      console.log(`stage ${i} failed: ${String(e.stderr).trim()}`);
      if (attempt >= 4) process.exit(1);
      sleep(60000);
    }
  }
}
EOF
node file.mjs

